  "@type": "FAQPage",
  "mainEntity": [
    {
      "@type": "Question",
      "name": "When was Shalimar Corp founded and who runs it?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Shalimar Corp Limited was established in 1988 and is headquartered at Shalimar Titanium, Vibhuti Khand, Gomti Nagar, Lucknow (Shalimar Corp website). Khalid Masood is its Managing Director (Realty Today, 1 Oct 2026) and Kunal Seth is a Director (ThePrint / ANI, 14 Jul 2026)."
      }
    },
    {
      "@type": "Question",
      "name": "Where is Shalimar OneWorld?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Shalimar OneWorld is an integrated township at Village Baghamau, Gomti Nagar Extension, near Amar Shaheed Path (Realty Doctors). It is registered with UP RERA phase by phase, so each tower or block has its own RERA number."
      }
    },
    {
      "@type": "Question",
      "name": "Is Shalimar Mannat in Lucknow or Barabanki?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Shalimar Mannat is marketed on Faizabad Road, Lucknow, but UP RERA lists Mannat Phase-1 (UPRERAPRJ8345) in Barabanki district, Nawabganj tehsil (RERA record). Property is registered at the sub-registrar office of the district where it lies."
      }
    },
    {
      "@type": "Question",
      "name": "Is Shalimar Gallant West RERA registered?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Yes. Shalimar Gallant West is registered as UPRERAPRJ569037, approved on 20 October 2022, with 69 apartments and a completion date of 20 October 2026 in the RERA record (RERA record). Check up-rera.in for any extension before you book."
      }
    },
    {
      "@type": "Question",
      "name": "How do I check the RERA status of a Shalimar project?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Go to up-rera.in, search the project by its RERA number, and check four things: the promoter name, the completion date and any extension, the latest quarterly progress report, and the carpet area of your unit type. All four must match your agreement."
      }
    },
    {
      "@type": "Question",
      "name": "Who is the promoter of Shalimar OneWorld phases on RERA?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "It varies by phase. For example, Whispering Woods (GH-14) is registered by M/s Shalimar Lakecity Private Limited (formerly M/s ANS Developers Private Limited) as UPRERAPRJ380751 (RERA record), while Gallant West is registered by M/s Shalimar Corp Ltd. Your agreement should name the same company as the RERA record."
      }
    }
  ]
}
